 document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{activeType=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===activeType));renderCatalog();});
 document.querySelectorAll('[data-category]').forEach(a=>a.onclick=()=>{activeType=a.dataset.category;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===activeType));renderCatalog();});
