 document.querySelector('#panel-compare').onclick=()=>{if(!comparison.has(activeModel.id)){if(comparison.size>=3){notify('Можно сравнить до трёх моделей');return;}comparison.add(activeModel.id);syncComparison();}openComparison();};
 
